#include <stdio.h>
#include <string.h>

void uart_init(void) {
    UCSR0B = (1 << RXEN0) | (1 << TXEN0)
    UCSR0C = (1 << UCSZ01) | (1 << UCSZ00)
    UBRR0H = 0
    UBRR0L = 103
}

int main(void) {
    uart_init()
    char buffer[64]
    strcpy(buffer, "Hello World\n")
    for (int i = 0; buffer[i]; i++) {
        while (!(UCSR0A & (1 << UDRE0)))
        UDR0 = buffer[i]
    }
    return 0
}
